import { Schema, SchemaGetter } from 'effect'

export const Timestamp = Schema.String
export type Timestamp = typeof Timestamp.Type

export const NullableTimestamp = Schema.NullOr(Timestamp)
export type NullableTimestamp = typeof NullableTimestamp.Type

export const WorkspaceId = Schema.String.check(Schema.isUUID())
export type WorkspaceId = typeof WorkspaceId.Type

export const UserId = Schema.NonEmptyString
export type UserId = typeof UserId.Type

export const AgentId = Schema.NonEmptyString
export type AgentId = typeof AgentId.Type

export const RunId = Schema.String.check(Schema.isUUID())
export type RunId = typeof RunId.Type

export const SourceId = Schema.NonEmptyString
export type SourceId = typeof SourceId.Type

export const SourceNamespace = Schema.String.check(
  Schema.isPattern(/^[a-z0-9]+(?:[-_][a-z0-9]+)*$/)
)
export type SourceNamespace = typeof SourceNamespace.Type

/**
 * Normalize an arbitrary free-text string into the lowercase-safe namespace
 * shape accepted by {@link SourceNamespace}: lowercase, non-alphanumerics
 * collapsed to `-`, leading/trailing `-` trimmed, capped at 40 chars.
 *
 * This is the single source of truth for the namespace slugify algorithm. The
 * frontend mirror lives in
 * `apps/web/modules/plugin-registry/namespace-suffix.ts`; the two must stay in
 * sync. Returns `''` for input that contains no alphanumerics — callers that
 * need a non-empty result should fall back to a default (e.g. `'source'`),
 * which is what {@link NormalizedSourceNamespace} does on decode.
 */
export function sanitizeNamespace(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
}

/**
 * A request-body namespace field that **sanitizes on decode** rather than
 * rejecting non-slug input. Any input string is run through
 * {@link sanitizeNamespace}; if that yields an empty string (input had no
 * usable alphanumerics) it falls back to `'source'`, matching the frontend
 * `nextFreeNamespace` default. The decoded value always satisfies
 * {@link SourceNamespace}. Encoding is identity.
 */
export const NormalizedSourceNamespace = Schema.String.pipe(
  Schema.decodeTo(SourceNamespace, {
    decode: SchemaGetter.transform((s: string) => sanitizeNamespace(s) || 'source'),
    encode: SchemaGetter.passthrough(),
  })
)
export type NormalizedSourceNamespace = typeof NormalizedSourceNamespace.Type

export const RegistrySlug = Schema.String.check(Schema.isPattern(/^[a-z0-9]+(?:-[a-z0-9]+)*$/))
export type RegistrySlug = typeof RegistrySlug.Type

export const CatalogSlug = Schema.String.check(Schema.isPattern(/^[a-z0-9]+(?:-[a-z0-9]+)*$/))
export type CatalogSlug = typeof CatalogSlug.Type

export const AdapterId = Schema.String.check(Schema.isPattern(/^[a-z0-9]+(?:[-_./][a-z0-9]+)*$/))
export type AdapterId = typeof AdapterId.Type

export const ToolId = Schema.NonEmptyString
export type ToolId = typeof ToolId.Type

export const ToolName = Schema.NonEmptyString
export type ToolName = typeof ToolName.Type

export const SecretName = Schema.String.check(Schema.isPattern(/^[A-Z][A-Z0-9_]*$/))
export type SecretName = typeof SecretName.Type

export const RegistryToolIdentifier = Schema.String.check(
  Schema.isPattern(/^[a-z0-9]+(?:_[a-z0-9]+)*$/)
)
export type RegistryToolIdentifier = typeof RegistryToolIdentifier.Type

export const JsonObject = Schema.Record(Schema.String, Schema.Unknown)
export type JsonObject = typeof JsonObject.Type
